  name: "interpolation_desugars_to_concat",
  internMode: "dict",
  ddl,
  rel_columns,
  rel_column_types,
  arrival_targets,
  boot: SUBSCRIBED_BOOT,
  final_select,
  host_plans,
  bind_plans,
  query_plans,
  subscribed_rels,
  rel_catalog,
  unsupported_execution,
  tick: run_tick,
